/**
 * Synthesized drum voices.
 *
 * Every voice is a small Web Audio graph rendered once into an AudioBuffer with
 * an OfflineAudioContext ("samples generated by synthesis"). Playback is then a
 * cheap buffer source per hit, which keeps CPU low and timing sample-accurate.
 * Tune and decay are baked in at render time, so changing them re-renders the
 * voice (a few milliseconds).
 *
 * The designs follow the classic analogue circuits (808/909 style) and common
 * UK Garage / House sound-design practice. No third-party audio is used.
 */

export const DRUM_SAMPLE_RATE = 44100;

interface RenderArgs {
  ctx: OfflineAudioContext;
  out: AudioNode;
  /** Tune ratio (2^(semitones/12)). */
  t: number;
  /** Decay multiplier. */
  d: number;
  noise: AudioBuffer;
}

interface VoiceDef {
  label: string;
  category: 'Kick' | 'Snare' | 'Clap' | 'Rim' | 'Closed Hat' | 'Open Hat' | 'Shaker' | 'Perc' | 'Cymbal';
  /** Base length in seconds before decay scaling. */
  length: number;
  tags: string[];
  render(a: RenderArgs): void;
}

// ---------------------------------------------------------------- helpers

function mulberry32(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let r = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

function makeNoise(ctx: BaseAudioContext, seconds: number): AudioBuffer {
  const len = Math.ceil(seconds * ctx.sampleRate);
  const buf = ctx.createBuffer(1, len, ctx.sampleRate);
  const data = buf.getChannelData(0);
  const rnd = mulberry32(0x6a09e667);
  for (let i = 0; i < len; i++) data[i] = rnd() * 2 - 1;
  return buf;
}

function noiseSrc(a: RenderArgs): AudioBufferSourceNode {
  const s = a.ctx.createBufferSource();
  s.buffer = a.noise;
  return s;
}

function gainEnv(ctx: BaseAudioContext, peak: number, attack: number, decay: number, start = 0): GainNode {
  const g = ctx.createGain();
  const p = g.gain;
  p.setValueAtTime(0, start);
  p.linearRampToValueAtTime(peak, start + Math.max(0.0005, attack));
  // setTarget gives the natural RC-style exponential tail of analogue drums.
  p.setTargetAtTime(0, start + attack, Math.max(0.002, decay / 4));
  return g;
}

function filter(ctx: BaseAudioContext, type: BiquadFilterType, freq: number, q = 0.707): BiquadFilterNode {
  const f = ctx.createBiquadFilter();
  f.type = type;
  f.frequency.value = Math.min(freq, ctx.sampleRate / 2 - 100);
  f.Q.value = q;
  return f;
}

function saturator(ctx: BaseAudioContext, drive: number): WaveShaperNode {
  const ws = ctx.createWaveShaper();
  const n = 2048;
  const curve = new Float32Array(n);
  const k = Math.max(0.01, drive);
  const norm = Math.tanh(k);
  for (let i = 0; i < n; i++) {
    const x = (i / (n - 1)) * 2 - 1;
    curve[i] = Math.tanh(k * x) / norm;
  }
  ws.curve = curve;
  ws.oversample = '4x';
  return ws;
}

function chain(...nodes: AudioNode[]): void {
  for (let i = 0; i < nodes.length - 1; i++) nodes[i].connect(nodes[i + 1]);
}

interface KickSpec {
  f0: number;
  sweepFrom: number;
  sweepTime: number;
  decay: number;
  drive: number;
  click: number;
  clickFreq: number;
  lowpass?: number;
}

function kick(a: RenderArgs, s: KickSpec): void {
  const { ctx, t, d } = a;
  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(s.sweepFrom * t, 0);
  osc.frequency.exponentialRampToValueAtTime(s.f0 * t, s.sweepTime);
  const amp = gainEnv(ctx, 1, 0.001, s.decay * d);
  const sat = saturator(ctx, s.drive);
  const lp = filter(ctx, 'lowpass', s.lowpass ?? 9000);
  chain(osc, amp, sat, lp, a.out);
  osc.start(0);
  // Transient click: band-limited noise burst.
  if (s.click > 0) {
    const n = noiseSrc(a);
    const bp = filter(ctx, 'bandpass', s.clickFreq, 1.2);
    const g = gainEnv(ctx, s.click, 0.0005, 0.012);
    chain(n, bp, g, a.out);
    n.start(0);
  }
}

interface SnareSpec {
  tones: number[];
  toneDecay: number;
  toneLevel: number;
  noiseHp: number;
  noiseLp: number;
  noiseDecay: number;
  noiseLevel: number;
  bandQ?: number;
}

function snare(a: RenderArgs, s: SnareSpec): void {
  const { ctx, t, d } = a;
  for (const f of s.tones) {
    const o = ctx.createOscillator();
    o.type = 'triangle';
    o.frequency.setValueAtTime(f * t * 1.25, 0);
    o.frequency.exponentialRampToValueAtTime(f * t, 0.02);
    const g = gainEnv(ctx, s.toneLevel / s.tones.length, 0.0008, s.toneDecay * d);
    chain(o, g, a.out);
    o.start(0);
  }
  const n = noiseSrc(a);
  const hp = filter(ctx, 'highpass', s.noiseHp * t);
  const lp = filter(ctx, s.bandQ ? 'peaking' : 'lowpass', s.noiseLp * t, s.bandQ ?? 0.707);
  if (s.bandQ) lp.gain.value = 6;
  const g = gainEnv(ctx, s.noiseLevel, 0.0008, s.noiseDecay * d);
  chain(n, hp, lp, g, a.out);
  n.start(0);
}

function clap(a: RenderArgs, centre: number, tail: number, spread = 0.011, bursts = 4): void {
  const { ctx, t, d } = a;
  const n = noiseSrc(a);
  const bp = filter(ctx, 'bandpass', centre * t, 1.1);
  const hp = filter(ctx, 'highpass', 500);
  const g = ctx.createGain();
  const p = g.gain;
  p.setValueAtTime(0, 0);
  for (let i = 0; i < bursts; i++) {
    const st = i * spread;
    p.setValueAtTime(0, st);
    p.linearRampToValueAtTime(i === bursts - 1 ? 1 : 0.8, st + 0.001);
    if (i < bursts - 1) p.setTargetAtTime(0.05, st + 0.001, 0.003);
  }
  p.setTargetAtTime(0, (bursts - 1) * spread + 0.002, (tail * d) / 4);
  chain(n, hp, bp, g, a.out);
  n.start(0);
}

const HAT_FREQS = [205.3, 304.4, 369.6, 522.7, 540.0, 800.0];

function metallicHat(a: RenderArgs, decay: number, opts: { noise: number; hp: number; bpf: number; metal: number }): void {
  const { ctx, t, d } = a;
  const bus = ctx.createGain();
  for (const f of HAT_FREQS) {
    const o = ctx.createOscillator();
    o.type = 'square';
    o.frequency.value = f * t * 1.7;
    const g = ctx.createGain();
    g.gain.value = opts.metal / HAT_FREQS.length;
    chain(o, g, bus);
    o.start(0);
  }
  if (opts.noise > 0) {
    const n = noiseSrc(a);
    const g = ctx.createGain();
    g.gain.value = opts.noise;
    chain(n, g, bus);
    n.start(0);
  }
  const bp = filter(ctx, 'bandpass', opts.bpf * Math.min(t, 1.4), 0.9);
  const hp = filter(ctx, 'highpass', opts.hp);
  const env = gainEnv(ctx, 1, 0.0005, decay * d);
  chain(bus, bp, hp, env, a.out);
}

function shaker(a: RenderArgs, centre: number, decay: number, attack: number): void {
  const { ctx, t, d } = a;
  const n = noiseSrc(a);
  const bp = filter(ctx, 'bandpass', centre * t, 1.4);
  const hp = filter(ctx, 'highpass', 3500);
  const g = gainEnv(ctx, 1, attack, decay * d);
  chain(n, bp, hp, g, a.out);
  n.start(0);
}

function tonalPerc(a: RenderArgs, freq: number, decay: number, sweep = 1.25, type: OscillatorType = 'sine', click = 0.2): void {
  const { ctx, t, d } = a;
  const o = ctx.createOscillator();
  o.type = type;
  o.frequency.setValueAtTime(freq * t * sweep, 0);
  o.frequency.exponentialRampToValueAtTime(freq * t, 0.015);
  const g = gainEnv(ctx, 1, 0.0006, decay * d);
  chain(o, g, a.out);
  o.start(0);
  if (click > 0) {
    const n = noiseSrc(a);
    const hp = filter(ctx, 'highpass', 3000);
    const ng = gainEnv(ctx, click, 0.0003, 0.006);
    chain(n, hp, ng, a.out);
    n.start(0);
  }
}

function rim(a: RenderArgs, f1: number, f2: number, decay: number): void {
  const { ctx, t, d } = a;
  const bus = ctx.createGain();
  for (const f of [f1, f2]) {
    const o = ctx.createOscillator();
    o.type = 'square';
    o.frequency.value = f * t;
    chain(o, bus);
    o.start(0);
  }
  const hp = filter(ctx, 'highpass', 600);
  const bp = filter(ctx, 'peaking', 2600 * t, 2);
  bp.gain.value = 8;
  const g = gainEnv(ctx, 0.5, 0.0003, decay * d);
  chain(bus, hp, bp, g, a.out);
}

