export type DrumVoiceId = keyof typeof DRUM_VOICES;

export function isDrumVoice(id: string): id is DrumVoiceId {
  return id in DRUM_VOICES;
}

const cache = new Map<string, Promise<AudioBuffer>>();

/** Renders a voice into an AudioBuffer (cached per voice/tune/decay). */
export function renderDrumVoice(id: DrumVoiceId, tune = 0, decay = 1): Promise<AudioBuffer> {
  const key = `${id}|${tune.toFixed(2)}|${decay.toFixed(2)}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const p = (async () => {
    const def = DRUM_VOICES[id] as VoiceDef;
    const seconds = def.length * Math.max(0.2, decay) + 0.05;
    const ctx = new OfflineAudioContext(1, Math.ceil(seconds * DRUM_SAMPLE_RATE), DRUM_SAMPLE_RATE);
    const out = ctx.createGain();
    out.connect(ctx.destination);
    def.render({ ctx, out, t: Math.pow(2, tune / 12), d: decay, noise: makeNoise(ctx, seconds) });
    const buf = await ctx.startRendering();
    normalize(buf, 0.89);
    fadeTail(buf, 0.01);
    return buf;
  })();
  cache.set(key, p);
  return p;
}

function normalize(buf: AudioBuffer, target: number): void {
  let peak = 0;
  for (let c = 0; c < buf.numberOfChannels; c++) {
    const d = buf.getChannelData(c);
    for (let i = 0; i < d.length; i++) peak = Math.max(peak, Math.abs(d[i]));
  }
  if (peak < 1e-6) return;
  const g = target / peak;
  for (let c = 0; c < buf.numberOfChannels; c++) {
    const d = buf.getChannelData(c);
    for (let i = 0; i < d.length; i++) d[i] *= g;
  }
}

function fadeTail(buf: AudioBuffer, seconds: number): void {
  const n = Math.min(buf.length, Math.floor(seconds * buf.sampleRate));
  for (let c = 0; c < buf.numberOfChannels; c++) {
    const d = buf.getChannelData(c);
    for (let i = 0; i < n; i++) d[d.length - 1 - i] *= i / n;
  }
}
